import{_ as t,a as r,o as s,a6 as i}from"./chunks/framework.CJDy2q7X.js";const b=JSON.parse('{"title":"Newsletter Subscribers","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/communications/subscribers/index.md","filePath":"api/rest-api/admin/marketing/communications/subscribers/index.md","lastUpdated":1787290888000}'),a={name:"api/rest-api/admin/marketing/communications/subscribers/index.md"};function o(n,e,c,d,m,l){return s(),r("div",null,e[0]||(e[0]=[i('<h1 id="newsletter-subscribers" tabindex="-1">Newsletter Subscribers <a class="header-anchor" href="#newsletter-subscribers" aria-label="Permalink to &quot;Newsletter Subscribers&quot;">​</a></h1><p>A <strong>newsletter subscriber</strong> is one email address signed up to receive newsletters and campaign emails for a storefront channel. The list is your newsletter audience — the people a campaign reaches. It mirrors the admin <strong>Marketing → Communications → Newsletter Subscribers</strong> screen.</p><h2 id="how-newsletter-subscribers-work" tabindex="-1">How newsletter subscribers work <a class="header-anchor" href="#how-newsletter-subscribers-work" aria-label="Permalink to &quot;How newsletter subscribers work&quot;">​</a></h2><p>Subscriber rows are created by the <strong>storefront</strong> — a shopper opts in through the newsletter sign-up (double opt-in). There is no admin &quot;create subscriber&quot; action; the admin only moderates the audience.</p><ul><li><strong>The audience.</strong> Each row pairs an <code>email</code> with the channel it subscribed on (a detail-only <code>channel</code> object <code>{ id, code, name }</code>, <code>null</code> on list rows). <code>isSubscribed</code> (<code>true</code> / <code>false</code>) is whether that address currently receives mail.</li><li><strong>Customer link.</strong> When a subscriber&#39;s email matches a registered customer, <code>customerId</code> and <code>customerName</code> resolve to that customer; otherwise both are <code>null</code> (a guest subscriber).</li><li><strong>Toggling.</strong> Setting <code>isSubscribed</code> flips the subscription. When the row is linked to a customer, the same flag is mirrored onto that customer&#39;s newsletter preference, so the two stay in sync.</li><li><strong>Deleting.</strong> Removing a subscriber first unsubscribes the linked customer (if any), then deletes the row.</li></ul><p><strong>Relation to other menus.</strong> A <a href="/api/rest-api/admin/marketing/communications/campaigns/">Campaign</a> sends its email template to the <strong>subscribed</strong> members of a customer group — only <code>isSubscribed: true</code> rows in that group receive the send.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/communications/subscribers-list.html">List</a></td><td><code>GET /api/admin/marketing/subscribers</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/subscribers-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/subscribers/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/subscribers-toggle.html">Toggle</a></td><td><code>PUT /api/admin/marketing/subscribers/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/subscribers-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/subscribers/{id}</code></td></tr></tbody></table><p>There is no create endpoint (subscriptions originate from the storefront) and no mass-delete.</p>',9)]))}const h=t(a,[["render",o]]);export{b as __pageData,h as default};
